'use strict';
// Reviewer-owned alternate fixture and literal oracle. No worker-test import.
const fs=require('fs'),path=require('path'),assert=require('assert');
const root=process.cwd(),out=path.join(root,'.cvf/runtime/cvf-expense-browser-local-review-20261010');
const builder=require(path.join(root,'scripts/cvf_expense_fixture_preview.cjs'));
const {chromium}=require(path.join(root,'EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web/node_modules/@playwright/test'));
const rows=[
 {id:'LOCAL-LATE',date:'2026-03-29',label:'Local late',amount:3},
 {id:'LOCAL-YEAR',date:'2027-03-29',label:'Local wrong year',amount:4},
 {id:'LOCAL-INVALID',date:'2026-03-32',label:'Local impossible',amount:5},
 {id:'LOCAL-EARLY',date:'2026-03-01',label:'Local early',amount:6},
 {id:'LOCAL-FEB',date:'2026-02-28',label:'Local other month',amount:7}
];
(async()=>{
 fs.mkdirSync(out,{recursive:true});const saved=builder.ROWS.primary.slice();let browser;
 const errors=[],external=[],cases=[];
 const before=builder.sha256(fs.readFileSync(builder.SOURCE));
 try{
  // ROWS is an exported helper input; replace only the runtime fixture, never source/filter or tracked bytes.
  builder.ROWS.primary.splice(0,builder.ROWS.primary.length,...rows);
  const built=await builder.buildPreview();fs.writeFileSync(path.join(out,'alternate.html'),built.html);
  browser=await chromium.launch();const context=await browser.newContext({viewport:{width:390,height:844}});
  await context.route('**/*',route=>{external.push(route.request().url());return route.abort();});
  const page=await context.newPage();page.setDefaultTimeout(15000);
  page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text());});
  await page.setContent(built.html);await page.waitForSelector('[data-expense-id]');
  const ids=()=>page.locator('[data-expense-id]').evaluateAll(es=>es.map(e=>e.dataset.expenseId));
  assert.deepStrictEqual(await ids(),['LOCAL-LATE','LOCAL-YEAR','LOCAL-EARLY','LOCAL-FEB']);cases.push('clear excludes impossible date, preserves supplied order');
  await page.locator('input[type=month]').fill('2026-03');
  assert.deepStrictEqual(await ids(),['LOCAL-LATE','LOCAL-EARLY']);cases.push('March2026 excludes wrong year, impossible date and other month');
  await page.locator('input[type=month]').fill('2027-03');
  assert.deepStrictEqual(await ids(),['LOCAL-YEAR']);cases.push('March2027 positive control');
  const height=await page.locator('input[type=month]').evaluate(e=>e.getBoundingClientRect().height);
  const changed=path.join(out,'drift.tsx'),sentinel=path.join(out,'sentinel.html');
  fs.writeFileSync(changed,Buffer.concat([fs.readFileSync(builder.SOURCE),Buffer.from('\n// local drift sentinel\n')]));
  fs.writeFileSync(sentinel,'LOCAL_SENTINEL_KEEP');const sentinelBefore=builder.sha256(fs.readFileSync(sentinel));
  let refused=false;try{await builder.writePreview({sourcePath:changed,output:sentinel});}catch(e){assert.match(e.message,/SOURCE_PIN_DRIFT/);refused=true;}
  assert.strictEqual(refused,true);assert.strictEqual(builder.sha256(fs.readFileSync(sentinel)),sentinelBefore);cases.push('source drift refused before sentinel overwrite');
  assert.deepStrictEqual(errors,[]);assert.deepStrictEqual(external,[]);assert.strictEqual(builder.sha256(fs.readFileSync(builder.SOURCE)),before);
  fs.writeFileSync(path.join(out,'probe-results.json'),JSON.stringify({status:'PASS',cases,fixture:rows,expectedMarch:['LOCAL-LATE','LOCAL-EARLY'],sourceSha256:before,htmlSha256:built.htmlSha256,browserVersion:browser.version(),monthInputHeightPx:height,externalRequests:external.length,pageErrors:errors.length,sentinelPreserved:true,method:'Exported ROWS.primary replaced in isolated Node process; actual pinned component unmodified; no worker-test imports.'},null,2));
  console.log('PASS independent fixture 3 cases + drift sentinel; month height='+height);
 }finally{builder.ROWS.primary.splice(0,builder.ROWS.primary.length,...saved);if(browser)await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
